/**
 * The registry, held to what it says about itself.
 *
 * `NEVER_BIND` HAS BEEN A PROMISE NOTHING KEPT. Its own docstring closed with "`keys.test.ts`
 * asserts it now", and there was no such file anywhere under `apps/web`: the list had no importer,
 * no reader and no test, on the one page of this product whose entire argument (19 §4) is that the
 * sheet cannot drift from what is bound because it is generated by reading the bindings. A list of
 * keys the product must never take, that nothing checks, is a comment.
 *
 * WHAT IT CHECKS IS THE REGISTRY AND NOT THE HANDLERS. Whether a given screen honours a binding is
 * a browser question and the four browser gates ask it. Whether the product has quietly claimed a
 * chord the browser owns, or printed the same key twice in one scope, or marked a chord `bare`, is
 * a question about this file's own data, and it is answerable here in milliseconds.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

import { BINDINGS, NEVER_BIND, SCOPE_ORDER, SCROLL_KEYS, type Binding } from './bindings.ts';

/**
 * A printed chord in the spelling `NEVER_BIND` uses.
 *
 * The sheet prints `⌘⇧K` because that is what a person reads on a key cap; the list of chords the
 * browser owns is written `Mod+Shift+K` because that is the spelling Chrome's extension API uses
 * and the list was copied from it. One of the two has to be translated to compare them, and it is
 * this one, because the printed form is the product and the list is the reference.
 */
const chords = (b: Binding): string[] =>
  b.key
    .split(/\s{2,}/u)
    .map((one) => one.trim())
    .filter((one) => one !== '')
    .map((one) => {
      const mod = one.includes('⌘') || one.includes('Mod');
      const shift = one.includes('⇧');
      const alt = one.includes('⌥');
      const rest = one.replace(/[⌘⇧⌥]/gu, '');
      return [...(mod ? ['Mod'] : []), ...(alt ? ['Alt'] : []), ...(shift ? ['Shift'] : []), rest].join('+');
    });

test('NO BINDING CLAIMS A CHORD THE BROWSER OWNS, which nothing checked', () => {
  const taken = new Set(NEVER_BIND);
  for (const b of BINDINGS)
    for (const chord of chords(b))
      assert.ok(!taken.has(chord), `${b.id} binds ${chord}, which is on NEVER_BIND`);
});

test('and the list it is checked against is not empty, which would make the check silent', () => {
  /* A SET BUILT FROM AN EMPTY LIST PASSES EVERY MEMBERSHIP TEST. The assertion above would then be
     a loop that runs and proves nothing, which is the shape this repository exists to catch. */
  assert.ok(NEVER_BIND.length > 20, 'NEVER_BIND has been emptied and the test above now asserts nothing');
  assert.ok(NEVER_BIND.includes('Mod+T'), 'the new tab chord is not on the list, so the list is not the list');
});

test('A KEY MEANS ONE THING IN ONE SCOPE, and the sheet prints it once', () => {
  const seen = new Map<string, string>();
  for (const b of BINDINGS)
    for (const chord of chords(b)) {
      const at = `${b.scope} ${chord}`;
      const already = seen.get(at);
      assert.equal(already, undefined, `${b.id} and ${already} both bind ${chord} in ${b.scope}`);
      seen.set(at, b.id);
    }
});

test('`bare` means the row holds a single CHARACTER key, which is what the switch silences', () => {
  /* IT IS NOT "has no modifier", WHICH IS THE READING THAT LOOKS RIGHT AND IS NOT. `Esc`, `Enter`,
     the arrows, `Home`, `Delete` and `F2` carry no modifier and are marked `bare: false`, correctly:
     WCAG 2.1.4 is about single-character keys, and a `Character keys: off` switch that silenced
     Escape would take the one key that closes things.

     AND IT IS A PROPERTY OF THE ROW, NOT OF EACH CHORD. `select` prints `x  ⇧x  ⌘a` and `copy-id`
     prints `y  ⇧Y`, so a row is bare when ANY of its chords is a character, and the switch silences
     that half of the row. What would be a lie is a row marked bare with no character key in it, or a
     row holding one and saying otherwise.

     THE REASON THIS ASSERTION GAVE FOR ITSELF WAS FALSE, and it was written here, today: "because
     the switch reads this flag and nothing else". The switch is `chars.ts:33`, and it reads
     `e.key.length === 1` and the cookie. It has never touched the registry and cannot: it is handed
     a `KeyboardEvent`, not a `Binding`. At the moment that sentence was written the flag was
     written on all forty-five rows and read by nothing but the test below it, so the justification
     offered for the duplicate was the one thing that was not true of it.

     What reads it now is `ui/Keymap.svelte`, which dims and marks the rows the switch has silenced,
     and the test after this one holds it to that. Two readers that must agree is a reason for a
     stored flag; one reader that recomputes it is not. */
  /* `+` IS A CHARACTER TOO: the quick add's key is one, and `chars.ts` silences it like any letter. So is `[`, the
     sidebar's key. */
  const character = (token: string) => /^[\p{L}\p{N},./?+[\]]$/u.test(token) || /^[0-9]–[0-9]$/u.test(token);
  for (const b of BINDINGS) {
    const tokens = b.key.split(/\s+/u).filter((t) => t !== '');
    const holds = tokens.some((t) => character(t));
    assert.equal(holds, b.bare, `${b.id} prints ${b.key} and says bare: ${b.bare}`);
  }
});

test('and something OUTSIDE this file reads `bare`, which for a long time nothing did', () => {
  /**
   * A STORED FLAG WITH ONE READER, AND THE READER IS THE TEST THAT DERIVES IT, IS NOT A FIELD.
   *
   * A repository-wide grep for the identifier used to return the type declaration, the forty-five
   * rows, and the assertion above, which recomputes the value from `binding.key` with its own
   * predicate. Delete `bare` from the type and from every row and nothing in the running product
   * changes: only this file goes red, about the field it was the sole reader of.
   *
   * The registry is data and this is the column that says which half of it the accessibility
   * switch takes away, so the answer was a reader rather than a deletion. `Keymap.svelte` is a
   * `.svelte` file and `node --test` cannot import it, so this reads it as TEXT, which is the
   * technique `palette.test.ts` already uses on this same registry and for the same reason.
   */
  const sheet = readFileSync(new URL('../ui/Keymap.svelte', import.meta.url), 'utf8');
  const code = sheet.replace(/<!--[\s\S]*?-->/gu, '');
  assert.match(code, /binding\.bare/u, 'the sheet does not read `bare`, so nothing outside this file does');
  /* AND IT MUST BE ABLE TO KNOW THE SWITCH IS OFF, or the mark is drawn never and the read is
     decorative. */
  assert.match(code, /silenced/u, 'the sheet reads `bare` but cannot tell whether the switch is off');
});

test('every binding is in a scope the sheet draws, or it is printed nowhere', () => {
  /* THE SHEET WALKS `SCOPE_ORDER`. A binding in a scope missing from that list is bound, real, and
     invisible on the one page that documents the keyboard. */
  const drawn = new Set<string>(SCOPE_ORDER);
  for (const b of BINDINGS) assert.ok(drawn.has(b.scope), `${b.id} is in scope ${b.scope}, which the sheet never draws`);
});

test('and every id is said once, because the sheet is keyed on it', () => {
  const ids = BINDINGS.map((b) => b.id);
  assert.equal(new Set(ids).size, ids.length, 'two bindings share an id');
});

test('the keys a page scrolls with are never claimed as bindings', () => {
  /* `SCROLL_KEYS` HAD NO READER EITHER. Space and the page keys are how a person reads a long list;
     a product that takes one of them has taken reading itself, and the loss is silent because the
     press appears to do the thing that was bound. */
  const scroll = new Set<string>(SCROLL_KEYS);
  for (const b of BINDINGS)
    for (const chord of chords(b))
      assert.ok(!scroll.has(chord), `${b.id} binds ${chord}, which is how a page scrolls`);
});
